import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DyZQ0-wY.js";const u=JSON.parse('{"title":"Tips and FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"footnotes/tips.md","filePath":"footnotes/tips.md"}'),s={name:"footnotes/tips.md"};function n(i,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="tips-and-faq" tabindex="-1">Tips and FAQ <a class="header-anchor" href="#tips-and-faq" aria-label="Permalink to &quot;Tips and FAQ&quot;">​</a></h1><h2 id="tips-for-learning-a-chart" tabindex="-1">Tips for learning a chart <a class="header-anchor" href="#tips-for-learning-a-chart" aria-label="Permalink to &quot;Tips for learning a chart&quot;">​</a></h2><ul><li><strong>Start slow.</strong> Set the playback rate to 50% or 75%, and speed it back up as the steps start to feel natural.</li><li><strong>Watch before you dance.</strong> Play a section once just to watch the bot&#39;s feet, then dance it.</li><li><strong>Practice one section at a time.</strong> Click the note layout on the right, or press <kbd>Page Up</kbd>, to go back and repeat a hard part.</li><li><strong>Listen to the steps.</strong> Turn on the clap (<kbd>F7</kbd>) to hear a tick on every arrow.</li><li><strong>Find a comfortable scroll speed.</strong> Lower it if the arrows rush past, and raise it if they bunch up.</li><li><strong>Learn the patterns&#39; names.</strong> Crossovers, footswitches, jacks and brackets come up in many charts. The <a href="./../parity.html#tech-notation">parity checking</a> page explains them.</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="the-dancing-bot-doesn-t-appear" tabindex="-1">The dancing bot doesn&#39;t appear <a class="header-anchor" href="#the-dancing-bot-doesn-t-appear" aria-label="Permalink to &quot;The dancing bot doesn&#39;t appear&quot;">​</a></h3><p>The bot works with dance single, dance double, pump single and pump double charts. For long charts, it can take a moment to work out the footing before the bot appears.</p><h3 id="the-bot-s-feet-look-wrong" tabindex="-1">The bot&#39;s feet look wrong <a class="header-anchor" href="#the-bot-s-feet-look-wrong" aria-label="Permalink to &quot;The bot&#39;s feet look wrong&quot;">​</a></h3><p>The footing is a prediction from SMEditor&#39;s <a href="./../parity.html">parity checker</a>. It&#39;s right for most charts, but some patterns, such as decorative mines or brackets, can confuse it. You can correct individual steps in the chart editor, as described in <a href="./../parity.html#correcting-the-parity-checker">Correcting the parity checker</a>.</p><h3 id="my-link-doesn-t-load" tabindex="-1">My link doesn&#39;t load <a class="header-anchor" href="#my-link-doesn-t-load" aria-label="Permalink to &quot;My link doesn&#39;t load&quot;">​</a></h3><p>Check that the link points straight to the <code>.sm</code> or <code>.ssc</code> file, that the music file is next to it, and that the site lets other pages read the files. Links from GitHub&#39;s <strong>Raw</strong> button work. See <a href="./loading-songs.html#from-a-link">Loading songs</a>.</p><h3 id="there-s-no-sound" tabindex="-1">There&#39;s no sound <a class="header-anchor" href="#there-s-no-sound" aria-label="Permalink to &quot;There&#39;s no sound&quot;">​</a></h3><p>Browsers only play sound after you interact with the page, so press play once. To change the volume, press <kbd>Alt</kbd>+<kbd>↑</kbd> or <kbd>Alt</kbd>+<kbd>↓</kbd>, or use the volume controls in the chart editor&#39;s top bar.</p><h3 id="can-i-use-a-dance-pad" tabindex="-1">Can I use a dance pad? <a class="header-anchor" href="#can-i-use-a-dance-pad" aria-label="Permalink to &quot;Can I use a dance pad?&quot;">​</a></h3><p>Footnotes doesn&#39;t need one: you can dance on the floor and follow the bot. To get timing judgments, press <kbd>P</kbd> to play along with keyboard keys or a dance pad that sends key presses. See <a href="./controls.html#playing-along">Playing along</a>.</p><h3 id="is-footnotes-the-same-as-smeditor" tabindex="-1">Is Footnotes the same as SMEditor? <a class="header-anchor" href="#is-footnotes-the-same-as-smeditor" aria-label="Permalink to &quot;Is Footnotes the same as SMEditor?&quot;">​</a></h3><p>Footnotes is built on <a href="https://github.com/tillvit/smeditor" target="_blank" rel="noreferrer">SMEditor</a>, an open source StepMania chart editor by tillvit. It adds the practice mode and this site. The full chart editor is still there: press <strong>Exit practice</strong> to use it.</p>',16)])])}const b=t(s,[["render",n]]);export{u as __pageData,b as default};
